sql_generado:
SELECT ROUND(AVG(r.numero_personas), 2) AS promedio_personas
FROM reservas r
JOIN v_reservas_detalle vd ON vd.reserva_id = r.reserva_id;

SELECT COUNT(*) AS total_reservas
FROM v_reservas_detalle
WHERE DATE_TRUNC('month', fecha_reserva) = DATE_TRUNC('month', CURRENT_DATE);

SELECT COALESCE(SUM(CASE WHEN tipo IN ('ingreso_reserva','ingreso_consumo','ingreso_adicional') THEN monto ELSE 0 END), 0) AS ingresos_mes_pasado
FROM transacciones_financieras tf
WHERE DATE_TRUNC('month', fecha_transaccion) = (CURRENT_DATE - INTERVAL '1 month');

SELECT COUNT(*) AS total_reservas
FROM reservas r
WHERE r.estado = 'completada';

SELECT COUNT(*) AS total_canceladas
FROM reservas
WHERE estado = 'cancelada';

SELECT COUNT(*) AS total_reservas
FROM v_reservas_detalle
WHERE canal = 'whatsapp';

SELECT COALESCE(SUM(CASE WHEN tf.tipo = 'gasto_operativo' THEN ABS(tf.monto) ELSE 0 END), 0) AS gasto_operativo_total
FROM transacciones_financieras tf
LEFT JOIN reservas r ON r.reserva_id = tf.reserva_id;

SELECT COUNT(*) AS total_reservas
FROM v_reservas_detalle
WHERE es_temporada_alta = TRUE;

SELECT COALESCE(SUM(CASE WHEN tf.tipo IN ('ingreso_reserva','ingreso_consumo','ingreso_adicional') THEN monto ELSE 0 END), 0) AS ingresos_semana
FROM transacciones_financieras tf
WHERE fecha_transaccion >= DATE_TRUNC('week', CURRENT_DATE);

SELECT COALESCE(SUM(CASE WHEN tf.tipo = 'gasto_operativo' THEN ABS(tf.monto) ELSE 0 END), 0) AS gastos_operativos
FROM transacciones_financieras tf
WHERE fecha_transaccion >= DATE_TRUNC('week', CURRENT_DATE);

SELECT COALESCE(SUM(CASE WHEN tf.tipo IN ('ingreso_reserva','ingreso_consumo','ingreso_adicional') THEN tf.monto ELSE 0 END), 0) AS ingreso_total
FROM transacciones_financieras tf
LEFT JOIN reservas r ON r.reserva_id = tf.reserva_id;

SELECT COUNT(*) AS total_reservas_por_estado
FROM (
  SELECT r.estado, COUNT(*) AS cantidad_reservas
  FROM reservas r
  GROUP BY r.estado
) sub;

SELECT COUNT(*) AS total_clientes_recurrentes
FROM clientes
WHERE es_recurrente = TRUE;

SELECT COUNT(*) AS total_reservas
FROM reservas r
WHERE DATE(r.fecha_reserva) = CURRENT_DATE;

SELECT COALESCE(SUM(CASE WHEN tf.tipo IN ('ingreso_reserva','ingreso_consumo','ingreso_adicional') THEN tf.monto ELSE 0 END), 0) AS ingresos_ayer
FROM transacciones_financieras tf
WHERE fecha_transaccion = CURRENT_DATE - 1;
